
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_tau_hcth_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_tau_hcth", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.481327694627772e+00, -4.387761938961305e+00, -4.256821965528103e+00, -4.075823741380774e+00, -3.830095054490647e+00, -3.505170303507271e+00, -3.091643438105413e+00, -2.591955307525220e+00, -2.023347921716688e+00, -1.459315406066989e+00, -1.067507667163296e+00, -7.330785307603555e-01, -6.397806316948573e-01, -5.039184834693093e-01, -3.481078656406561e-01, -2.453805002492299e-01, -2.156431450613940e-01, -1.024319852465271e-01, -2.304100287808339e-02, -2.595465182674394e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


